VAR Y = SELECTEDVALUE('Kalender'[År], YEAR(TODAY()))
VAR YearStart = DATE(Y,1,1)
VAR YearEnd   = DATE(Y,12,31)
RETURN
SUMX (
    VALUES ( 'ViewDimAnställdSCD2'[Anställd SK] ),
    VAR EmpStart =
        CALCULATE ( MIN ( 'ViewDimAnställdSCD2'[Tillträde SCD2 Justerad Datum] ) )
    VAR EmpEndRaw =
        CALCULATE ( MAX ( 'ViewDimAnställdSCD2'[Tillträde SCD2 Justerad t.o.m. Datum]  ) )
    VAR EmpEnd = COALESCE ( EmpEndRaw, DATE(9999,12,31) )

    VAR S = MAX ( EmpStart, YearStart )
    VAR E = MIN ( EmpEnd,   YearEnd )

VAR result = 
    IF (
        ISBLANK(EmpStart) || S > E,
        BLANK(),
        -- summera 12 månadsfraktioner för året, per SK
        SUMX (
            GENERATESERIES(1,12,1),
            VAR m  = [Value]
            VAR MS = DATE(Y, m, 1)
            VAR ME = EOMONTH(MS, 0)
            VAR DaysInMonth = DAY(ME)
            VAR OverlapStart = MAX(S, MS)
            VAR OverlapEnd   = MIN(E, ME)
            VAR OverlapDays  = MAX(0, DATEDIFF(OverlapStart, OverlapEnd, DAY) + 1)
            RETURN MIN(1, DIVIDE(OverlapDays, DaysInMonth))
        )
    )

RETURN IF([New_FTEFöreJustering] <> 0, result)
